import{_ as t,o as i,c as a,a5 as o}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Editor AI Content popup","description":"","frontmatter":{},"headers":[],"relativePath":"feature/editor-ai-content-popover/spec.md","filePath":"feature/editor-ai-content-popover/spec.md"}'),n={name:"feature/editor-ai-content-popover/spec.md"};function r(s,e,l,c,d,p){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="editor-ai-content-popup" tabindex="-1">Editor AI Content popup <a class="header-anchor" href="#editor-ai-content-popup" aria-label="Permalink to &quot;Editor AI Content popup&quot;">​</a></h1><p>Replace the editor&#39;s permanent AI sidebar with an <code>AI Content</code> button beside the autosave badge, giving the post editor more width.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Hovering with a mouse opens a compact, chat-like floating assistant; clicking or pressing Enter/Space also opens it.</li><li>The assistant contains the existing Text, Image and Video forms, generation feedback and apply actions.</li><li>Moving from the button into the assistant or editing a field does not dismiss it. Close button, Escape and clicking outside dismiss it.</li><li>Closing and reopening preserves the current form state and does not cancel active generation. Existing caption dialogs and result insertion still work.</li><li>The editor and resizable Live Preview use the available width without an empty AI column. Read-only tasks cannot invoke AI tools.</li><li>Live Preview stays to the right of the editor from 1024 CSS pixels upward, including 1024/1100px laptop layouts; below that, it stacks for mobile/tablet.</li><li>Live Preview always offers Facebook, Instagram, TikTok and Threads using the existing platform mockups. Switching a preview does not change the platforms selected for publishing; buttons remain visible within the narrow preview column.</li><li>Popup width/height stay within the viewport on desktop, tablet and mobile.</li><li>New labels use parallel <code>editor.studio.aiContent.{button,description,greeting,close}</code> keys in Vietnamese and English. The autosave badge uses <code>editor.studio.autosaveLabel</code> in both locales.</li><li>Editor translation updates during development refresh visible labels without requiring a page reload or discarding the current draft.</li><li>Use existing BrandHub typography, semantic colors and controls in light and dark themes.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Keep the existing AI API contracts, generation results and credit handling. This is an editor layout and interaction change, not a new conversational backend or a replacement of the AI forms.</p>',6)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
